{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase","requirement":"Landlords of rent-stabilized units may raise rent once every 12 months by the allowable percentage (or to market rate only for listed reasons). From February 2, 2026, the utility add-on and the dependent add-on increase are no longer permitted.","key_value":"Once every 12 months, allowable rent increase percentage","coverage_conditions":"Generally covers rental properties first built on or before October 1, 1978, plus replacement units, apartments, condos, townhomes, duplexes, ADUs/JADUs, hotel rooms occupied over 30 days, mobile homes and units attached to commercial buildings.","applicability":{"conditions":[],"per_tenancy":"Rent amount not regulated for condominium or townhome tenancies that commenced after December 31, 1995.","coverage_quotes":[]},"exemptions":"Rent not regulated for condominium or townhome tenancies commenced after December 31, 1995; landlords may apply for a luxury exemption based on rent charged on or before May 31, 1978; temporary exemptions available.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction","requirement":"A landlord may end an RSO tenancy only for the listed at-fault or no-fault reasons, must file the termination notice with LAHD within three business days of service, and must pay relocation assistance for no-fault evictions.","key_value":"Notice filed within 3 business days; relocation assistance for no-fault evictions","coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance (RSO).","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"L.A.M.C. §§ 151.09, 165.05","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"security_deposits","lifecycle":"enacted","title":"Los Angeles RSO interest on security deposits","requirement":"The Rent Stabilization Ordinance requires landlords to pay interest on tenants' security deposits.","key_value":null,"coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance (RSO).","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Interest Payments on Security Deposits","interaction":null,"relations":[],"confidence":0.5,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","n_rules":3,"note":null}

